parameters.jsCode:
// Selective event consumption — only mark events consumed when actions succeeded
const allItems = $input.all();
const failedEventIds = new Set();
const succeededEventIds = new Set();

for (const item of allItems) {
  const d = item.json;
  const eventId = d.eventId;
  if (!eventId) continue;

  // Check if this action had an error
  if (d.error || d.statusCode >= 400 || d.statusMessage) {
    failedEventIds.add(eventId);
  } else {
    succeededEventIds.add(eventId);
  }
}

// Only consume events where no actions failed
const safeIds = [...succeededEventIds].filter(id => !failedEventIds.has(id));
if (safeIds.length === 0) {
  return [{ json: { records: [], _skip: true, failedCount: failedEventIds.size } }];
}

const records = safeIds.map(id => ({
  id,
  fields: { consumed_by: 'orchestrator' }
}));
const batches = [];
for (let i = 0; i < records.length; i += 10) {
  batches.push(records.slice(i, i + 10));
}
return batches.map(batch => ({ json: { records: batch, failedCount: failedEventIds.size } }));

// Mark events consumed even when no decisions were generated
const eventIds = $('Parse & Validate Decisions').first().json.eventIds || [];
if (eventIds.length === 0) {
  return [];
}
const records = eventIds.map(id => ({
  id,
  fields: { consumed_by: 'orchestrator' }
}));
const batches = [];
for (let i = 0; i < records.length; i += 10) {
  batches.push(records.slice(i, i + 10));
}
return batches.map(batch => ({ json: { records: batch } }));

// Log fetch errors to Agent_Events
const data = $input.first().json;
if (!data._error) return [];
const payload = {
  fetchErrors: data.fetchErrors,
  timestamp: new Date().toISOString()
};
return [{ json: {
  records: [{
    fields: {
      agent: 'orchestrator',
      event_type: 'system_error',
      severity: 'high',
      message: 'Orchestrator fetch failed: ' + data.fetchErrors.join('; '),
      payload: JSON.stringify(payload),
      created_at: new Date().toISOString()
    }
  }]
} }];

// Handle proactive triggers — format for Slack notification
const d = $json;
const action = d.action || 'unknown';
const emoji = action === 'suggest_rotation' ? ':arrows_counterclockwise:' : action === 'suggest_repurpose' ? ':recycle:' : ':robot_face:';
const label = action === 'suggest_rotation' ? 'Creative Rotation Suggested' : action === 'suggest_repurpose' ? 'Content Repurposing Opportunity' : 'Proactive Suggestion';

return [{ json: {
  ...d,
  _emoji: emoji,
  _label: label,
  _slackText: emoji + ' *' + label + '*\n' + (d.message || 'No details') + '\n\n_Brand:_ ' + (d.brand_name || 'N/A') + '\n_Action:_ `' + action + '`\n_Detected by:_ Orchestrator v2 (pattern analysis)'
} }];

// ============================================================
// Curate Learnings — decay, merge duplicates, promote cross-brand
// Runs after decision execution to avoid parallel-merge issues
// ============================================================

let learnings = [];
try {
  learnings = $('Fetch System Learnings').first().json.records || [];
} catch(e) { return [{ json: { updates: [], _skip: true } }]; }

if (learnings.length === 0) return [{ json: { updates: [], _skip: true } }];

const now = new Date();
const updates = [];
const toRetire = [];
const toMerge = [];

// 1. DECAY: Reduce decay_score based on age since last_confirmed_at
for (const l of learnings) {
  const f = l.fields;
  const lastConfirmed = f.last_confirmed_at ? new Date(f.last_confirmed_at) : new Date(f.created_at);
  const weeksSinceConfirmed = (now - lastConfirmed) / (7 * 24 * 3600000);
  const currentDecay = f.decay_score !== undefined ? f.decay_score : (f.confidence || 5);
  const newDecay = Math.max(0, currentDecay - (weeksSinceConfirmed * 0.1));

  // Retire if below 3.0
  if (newDecay < 3.0) {
    toRetire.push({ id: l.id, fields: { active: false, decay_score: newDecay } });
  } else if (Math.abs(newDecay - currentDecay) > 0.05) {
    // Only update if decay changed meaningfully
    updates.push({ id: l.id, fields: { decay_score: Math.round(newDecay * 10) / 10 } });
  }
}

// 2. MERGE: Find similar learnings (same brand + >70% word overlap)
function wordSet(text) {
  return new Set((text || '').toLowerCase().replace(/[^a-z0-9\s]/g, '').split(/\s+/).filter(w => w.length > 2));
}
function overlap(a, b) {
  const setA = wordSet(a);
  const setB = wordSet(b);
  if (setA.size === 0 || setB.size === 0) return 0;
  let common = 0;
  for (const w of setA) if (setB.has(w)) common++;
  return common / Math.max(setA.size, setB.size);
}

const merged = new Set();
for (let i = 0; i < learnings.length; i++) {
  if (merged.has(learnings[i].id)) continue;
  for (let j = i + 1; j < learnings.length; j++) {
    if (merged.has(learnings[j].id)) continue;
    const fi = learnings[i].fields;
    const fj = learnings[j].fields;
    // Same brand (or both agency-wide)
    if ((fi.brand_name || '') !== (fj.brand_name || '')) continue;
    const sim = overlap(fi.insight || fi.learning || '', fj.insight || fj.learning || '');
    if (sim > 0.7) {
      // Merge: keep the one with higher confidence, retire the other
      const keepIdx = (fi.confidence || 0) >= (fj.confidence || 0) ? i : j;
      const retireIdx = keepIdx === i ? j : i;
      const keep = learnings[keepIdx];
      const retire = learnings[retireIdx];
      toMerge.push({
        keep: { id: keep.id, fields: {
          times_confirmed: (keep.fields.times_confirmed || 1) + (retire.fields.times_confirmed || 1),
          decay_score: Math.max(keep.fields.decay_score || keep.fields.confidence || 5, retire.fields.decay_score || retire.fields.confidence || 5)
        }},
        retire: { id: retire.id, fields: { active: false } }
      });
      merged.add(retire.id);
    }
  }
}

// 3. PROMOTE: Brand-specific learning appearing in 3+ brands -> create agency-wide
const byInsight = {};
for (const l of learnings) {
  const f = l.fields;
  if (!f.brand_name) continue; // skip agency-wide
  const key = (f.category || '') + ':' + ((f.insight || f.learning || '').substring(0, 50));
  if (!byInsight[key]) byInsight[key] = { brands: new Set(), learning: f };
  byInsight[key].brands.add(f.brand_name);
}
const promotions = [];
for (const [key, data] of Object.entries(byInsight)) {
  if (data.brands.size >= 3) {
    // Check if agency-wide version already exists
    const existing = learnings.find(l => !l.fields.brand_name && overlap(l.fields.insight || l.fields.learning || '', data.learning.insight || data.learning.learning || '') > 0.7);
    if (!existing) {
      promotions.push({
        fields: {
          title: (data.learning.title || 'Promoted learning') + ' (cross-brand)',
          source_agent: 'orchestrator',
          category: data.learning.category,
          insight: data.learning.insight || data.learning.learning,
          evidence: 'Confirmed across brands: ' + Array.from(data.brands).join(', '),
          confidence: Math.min(10, (data.learning.confidence || 5) + 1),
          decay_score: Math.min(10, (data.learning.confidence || 5) + 1),
          times_confirmed: data.brands.size,
          last_confirmed_at: now.toISOString(),
          active: true,
          brand_name: '',
          industry: data.learning.industry || '',
          created_at: now.toISOString()
        }
      });
    }
  }
}

// Build batch update records
const allUpdates = [...updates];
for (const r of toRetire) allUpdates.push(r);
for (const m of toMerge) {
  allUpdates.push(m.keep);
  allUpdates.push(m.retire);
}

// Batch into groups of 10
const batches = [];
for (let i = 0; i < allUpdates.length; i += 10) {
  batches.push(allUpdates.slice(i, i + 10));
}

return [{ json: {
  updateBatches: batches,
  promotions: promotions,
  stats: {
    total: learnings.length,
    decayed: updates.length,
    retired: toRetire.length,
    merged: toMerge.length,
    promoted: promotions.length
  },
  _skip: allUpdates.length === 0 && promotions.length === 0
}}];

// ============================================================
// Write Curation Updates — prepare Airtable API call items
// Outputs one item per batch (PATCH for updates, POST for promotions)
// ============================================================

const { updateBatches, promotions } = $json;
const items = [];

// PATCH requests for decay updates, retirements, merges
if (updateBatches && updateBatches.length > 0) {
  for (const batch of updateBatches) {
    items.push({ json: {
      method: 'PATCH',
      body: { records: batch }
    }});
  }
}

// POST request for promotions (new records)
if (promotions && promotions.length > 0) {
  // Batch promotions into groups of 10 too
  for (let i = 0; i < promotions.length; i += 10) {
    const batch = promotions.slice(i, i + 10);
    items.push({ json: {
      method: 'POST',
      body: { records: batch }
    }});
  }
}

if (items.length === 0) return [];
return items;

// Write individual proactive alert event to Agent_Events for dedup
const d = $input.first().json;
// Extract insight_key - it may be in the original decision data
// or passed through from the Slack node response
let insightKey = '';
let brandName = '';
let eventType = '';
let message = '';

// Try to get data from upstream split decisions
try {
  const splitItems = $('Split Decisions').all();
  for (const item of splitItems) {
    const ij = item.json;
    if (ij.type === 'pre_alert' || ij.type === 'proactive_trigger') {
      insightKey = ij.insight_key || '';
      brandName = ij.brand_name || '';
      eventType = ij.type || 'pre_alert';
      message = ij.message || '';
      break;  // Take the first proactive decision
    }
  }
} catch(e) {}

if (!insightKey && !brandName) {
  return [];  // Nothing to log
}

return [{ json: {
  records: [{
    fields: {
      agent: 'orchestrator',
      event_type: eventType,
      severity: 'info',
      brand_name: brandName,
      message: message.substring(0, 500),
      payload: JSON.stringify({ insight_key: insightKey, source: 'proactive_analysis' }),
      consumed_by: 'orchestrator',
      created_at: new Date().toISOString()
    }
  }]
} }];

// ============================================================
// Proactive Analysis v2 — WITH DEDUPLICATION + THROTTLING
// Generates deterministic insight_key per pattern.
// Checks recent proactive events (last 24h) to skip duplicates.
// Throttle: max 3 suggestions per run, max 1 per brand per 24h.
// ============================================================

const now = new Date();
const allCandidates = [];

// Safely fetch upstream data
let events = [], projects = [], brands = [], learnings = [], recentProactive = [];
try { events = $('Fetch Unprocessed Events').first().json.records || []; } catch(e) {}
try { projects = $('Fetch Active Projects').first().json.records || []; } catch(e) {}
try { brands = $('Fetch Brands').first().json.records || []; } catch(e) {}
try { learnings = $('Fetch System Learnings').first().json.records || []; } catch(e) {}
try { recentProactive = $('Fetch Recent Proactive Events').first().json.records || []; } catch(e) {}

// === BUILD DEDUP INDEX from recent proactive events ===
const recentKeys = new Set();
const recentBrandAlerts = {};  // brand_name -> count in last 24h
for (const rp of recentProactive) {
  const rpf = rp.fields || {};
  // Try to extract insight_key from payload JSON
  let insightKey = '';
  try {
    const payload = typeof rpf.payload === 'string' ? JSON.parse(rpf.payload) : (rpf.payload || {});
    insightKey = payload.insight_key || '';
  } catch(e) {}
  // Fallback key from event_type + brand_name + message prefix
  if (!insightKey) {
    insightKey = (rpf.event_type || '') + ':' + (rpf.brand_name || '') + ':' + ((rpf.message || '').substring(0, 80));
  }
  recentKeys.add(insightKey);
  const bn = rpf.brand_name || '';
  if (bn) recentBrandAlerts[bn] = (recentBrandAlerts[bn] || 0) + 1;
}

// Helper: hours since a date
function hoursSince(dateStr) {
  if (!dateStr) return 9999;
  return (now - new Date(dateStr)) / 3600000;
}

// Helper: check if insight_key was already sent
function alreadySent(key) {
  return recentKeys.has(key);
}

// Helper: check if brand exceeded 1 proactive alert per 24h
function brandThrottled(brandName) {
  if (!brandName) return false;
  return (recentBrandAlerts[brandName] || 0) >= 1;
}

// === 1. PIPELINE VELOCITY: warn at 75% of SLA thresholds ===
const slaThresholds = {
  'Research': { warn: 36, breach: 48 },
  'PM Review': { warn: 18, breach: 24 },
  'Script Writing': { warn: 54, breach: 72 },
  'Script Review': { warn: 36, breach: 48 },
  'In Progress': { warn: 54, breach: 72 }
};
for (const p of projects) {
  const pf = p.fields;
  const status = pf.status || '';
  const threshold = slaThresholds[status];
  if (!threshold) continue;
  const hrs = hoursSince(pf.updated_at || pf.created_at);
  if (hrs >= threshold.warn && hrs < threshold.breach) {
    const key = 'pipeline_velocity:' + (pf.client_code || p.id) + ':' + status;
    if (alreadySent(key) || brandThrottled(pf.brand_name)) continue;
    allCandidates.push({
      type: 'pre_alert',
      severity: 'info',
      brand_name: pf.brand_name || 'Unknown',
      project_id: p.id,
      client_code: pf.client_code || '',
      insight_key: key,
      message: (pf.brand_name || 'Project') + ' approaching SLA in "' + status + '" (' + Math.round(hrs) + 'h / ' + threshold.breach + 'h limit). Consider nudging.'
    });
  }
}

// === 2. TREND DETECTION: 2+ campaign_alerts for same brand -> suggest rotation ===
const alertsByBrand = {};
for (const e of events) {
  const ef = e.fields;
  if (ef.event_type === 'campaign_alert') {
    const bn = ef.brand_name || 'unknown';
    if (!alertsByBrand[bn]) alertsByBrand[bn] = [];
    alertsByBrand[bn].push(ef);
  }
}
for (const [brand, alerts] of Object.entries(alertsByBrand)) {
  if (alerts.length >= 2) {
    const key = 'suggest_rotation:' + brand;
    if (alreadySent(key) || brandThrottled(brand)) continue;
    const fatigueAlerts = alerts.filter(a => (a.message || '').toLowerCase().includes('fatigue'));
    allCandidates.push({
      type: 'proactive_trigger',
      action: 'suggest_rotation',
      brand_name: brand,
      insight_key: key,
      message: brand + ' has ' + alerts.length + ' campaign alerts' + (fatigueAlerts.length > 0 ? ' (including fatigue signals)' : '') + '. Consider creative rotation or new cycle.',
      webhook: '/webhook/ugc-research'
    });
  }
}

// === 3. RESOURCE FORECASTING: 3+ projects entering scripting -> pre-scout ===
const scriptingProjects = projects.filter(p =>
  p.fields.status === 'Script Writing' || p.fields.status === 'Research'
);
if (scriptingProjects.length >= 3) {
  const brandNames = scriptingProjects.map(p => p.fields.brand_name).filter(Boolean);
  const key = 'pre_scout:' + brandNames.sort().join(',');
  if (!alreadySent(key)) {
    allCandidates.push({
      type: 'pre_alert',
      severity: 'info',
      insight_key: key,
      message: scriptingProjects.length + ' projects in pipeline (' + brandNames.join(', ') + '). Consider pre-scouting creators to avoid bottleneck.',
      brand_name: brandNames[0] || ''
    });
  }
}

// === 4. CROSS-BRAND PATTERNS: learning confirmed 3x+ ===
for (const l of learnings) {
  const lf = l.fields;
  if (!lf.brand_name || !lf.industry) continue;
  if ((lf.times_confirmed || 0) < 3) continue;
  const sameBrands = brands.filter(b =>
    b.fields.industry === lf.industry &&
    b.fields.brand_name !== lf.brand_name
  );
  if (sameBrands.length > 0) {
    const key = 'cross_brand:' + l.id;
    if (alreadySent(key) || brandThrottled(lf.brand_name)) continue;
    allCandidates.push({
      type: 'pre_alert',
      severity: 'info',
      brand_name: lf.brand_name,
      insight_key: key,
      message: 'Learning "' + (lf.title || '').substring(0, 60) + '" confirmed ' + lf.times_confirmed + 'x for ' + lf.brand_name + '. May benefit: ' + sameBrands.map(b => b.fields.brand_name).join(', ') + ' (same industry: ' + lf.industry + ').'
    });
  }
}

// === 5. ANTICIPATORY TRIGGERS: scripts completed but not repurposed ===
for (const e of events) {
  const ef = e.fields;
  if (ef.event_type === 'phase_complete' && ef.agent === 'phase_3') {
    const hasRepurpose = events.some(e2 =>
      e2.fields.event_type === 'content_repurposed' &&
      e2.fields.brand_name === ef.brand_name
    );
    if (!hasRepurpose) {
      const key = 'suggest_repurpose:' + (ef.brand_name || '') + ':' + (ef.project_id || '');
      if (alreadySent(key) || brandThrottled(ef.brand_name)) continue;
      allCandidates.push({
        type: 'proactive_trigger',
        action: 'suggest_repurpose',
        brand_name: ef.brand_name || '',
        project_id: ef.project_id || '',
        insight_key: key,
        message: 'Scripts completed for ' + (ef.brand_name || 'brand') + ' but not yet repurposed. Trigger /repurpose to generate variations.',
        webhook: '/webhook/repurpose'
      });
    }
  }
}

// === GLOBAL THROTTLE: max 3 suggestions per run ===
const suggestions = allCandidates.slice(0, 3);

// Pass through to Build Orchestrator Prompt
return [{ json: {
  proactiveSuggestions: suggestions,
  suggestionCount: suggestions.length,
  _dedupStats: {
    candidatesBeforeDedup: allCandidates.length,
    recentProactiveEventsChecked: recentProactive.length,
    recentKeysKnown: recentKeys.size,
    brandThrottleCounts: recentBrandAlerts
  }
} }];

// ============================================================
// Build Orchestrator Prompt v2 — LLM-based reasoning
// WITH DEDUP CONTEXT: injects recently-sent proactive alerts
// Falls back to SLA-only detection if 0 events or Gemini fails
// ============================================================

const fetchResults = [
  { name: 'Events', data: $('Fetch Unprocessed Events').first().json },
  { name: 'Projects', data: $('Fetch Active Projects').first().json },
  { name: 'Brands', data: $('Fetch Brands').first().json }
];
const fetchErrors = [];
for (const fr of fetchResults) {
  if (fr.data.error || fr.data.statusCode >= 400 || (fr.data.statusMessage && fr.data.statusCode)) {
    fetchErrors.push(`${fr.name}: ${fr.data.error || fr.data.statusMessage || 'HTTP ' + fr.data.statusCode}`);
  }
}
if (fetchErrors.length > 0) {
  return [{ json: { decisions: [], eventIds: [], decisionCount: 0, eventCount: 0, _error: true, fetchErrors } }];
}

const events = $('Fetch Unprocessed Events').first().json.records || [];
const projects = $('Fetch Active Projects').first().json.records || [];
const brands = $('Fetch Brands').first().json.records || [];
const now = new Date();
const eventIds = events.map(e => e.id);

// Fetch system learnings (may be empty)
let learnings = [];
try {
  learnings = $('Fetch System Learnings').first().json.records || [];
} catch(e) { learnings = []; }

// Fetch recent proactive events for dedup context
let recentProactive = [];
try {
  recentProactive = $('Fetch Recent Proactive Events').first().json.records || [];
} catch(e) { recentProactive = []; }

// === SLA DETECTION (hardcoded fallback — always runs) ===
const slaDecisions = [];
for (const project of projects) {
  const pf = project.fields;
  const updatedAt = new Date(pf.updated_at || pf.created_at || now);
  const hoursInStatus = (now - updatedAt) / 3600000;

  if (pf.status === 'PM Review' && hoursInStatus > 24) {
    slaDecisions.push({
      type: 'sla_alert', severity: 'warning',
      project_id: project.id, brand_name: pf.brand_name,
      client_code: pf.client_code,
      message: pf.brand_name + ' stuck in PM Review for ' + Math.round(hoursInStatus) + 'h'
    });
  }
  if (pf.status === 'Script Review' && hoursInStatus > 48) {
    slaDecisions.push({
      type: 'sla_alert', severity: 'warning',
      project_id: project.id, brand_name: pf.brand_name,
      client_code: pf.client_code,
      message: pf.brand_name + ' stuck in Script Review for ' + Math.round(hoursInStatus) + 'h'
    });
  }
  if (pf.status === 'In Progress' && hoursInStatus > 72) {
    slaDecisions.push({
      type: 'sla_alert', severity: 'urgent',
      project_id: project.id, brand_name: pf.brand_name,
      client_code: pf.client_code,
      message: pf.brand_name + ' In Progress for ' + Math.round(hoursInStatus) + 'h \u2014 may be stuck'
    });
  }
}

// Read proactive suggestions BEFORE skip-check so they're never lost
const proactive = $('Proactive Analysis').first().json.proactiveSuggestions || [];

// If 0 events AND 0 proactive suggestions, output SLA decisions directly (skip Gemini)
if (events.length === 0 && proactive.length === 0) {
  return [{ json: {
    geminiBody: JSON.stringify({ contents: [{ role: 'user', parts: [{ text: 'No events to process.' }] }], generationConfig: { maxOutputTokens: 10 } }),
    decisions: slaDecisions,
    eventIds: [],
    decisionCount: slaDecisions.length,
    eventCount: 0,
    slaDecisions: slaDecisions,
    _skipGemini: true
  } }];
}

// === BUILD GEMINI PROMPT ===
let eventsText = '== CURRENT EVENTS (unprocessed) ==\n';
for (const e of events) {
  const f = e.fields;
  let payloadExcerpt = '';
  try { payloadExcerpt = (f.payload || '').substring(0, 200); } catch(x) {}
  eventsText += `[${e.id}] ${f.event_type} | agent: ${f.agent || 'unknown'} | brand: ${f.brand_name || 'N/A'} | project: ${f.project_id || 'N/A'} | severity: ${f.severity || 'info'} | ${f.message || ''} | payload: ${payloadExcerpt}\n`;
}

let projectsText = '\n== ACTIVE PROJECTS ==\n';
for (const p of projects) {
  const pf = p.fields;
  const updatedAt = new Date(pf.updated_at || pf.created_at || now);
  const hoursInStatus = Math.round((now - updatedAt) / 3600000);
  projectsText += `[${p.id}] ${pf.brand_name || 'Unknown'} | status: ${pf.status || 'N/A'} | ${hoursInStatus}h in status | scripts: ${pf.num_scripts || 0} | client: ${pf.client_code || 'N/A'} | goal: ${(pf.project_goal || 'Not defined').substring(0, 150)}\n`;
}

let brandsText = '\n== BRANDS ==\n';
for (const b of brands) {
  const bf = b.fields;
  brandsText += `[${b.id}] ${bf.brand_name || 'Unknown'} | industry: ${bf.industry || 'N/A'} | website: ${bf.website_url || 'N/A'}\n`;
}

let learningsText = '\n== SYSTEM LEARNINGS (top 20 by confidence) ==\n';
if (learnings.length > 0) {
  learnings.forEach((l, i) => {
    const lf = l.fields;
    learningsText += `[${i+1}] (${lf.category || 'general'}, confidence: ${lf.confidence || 'N/A'}) ${lf.title || 'Untitled'}: ${(lf.insight || lf.learning || lf.content || '').substring(0, 200)}\n`;
  });
} else {
  learningsText += 'No system learnings available.\n';
}

// Proactive suggestions already read above (before skip-check)
let proactiveText = '\n== PROACTIVE INSIGHTS (deterministic pattern detection, already deduplicated) ==\n';
if (proactive.length > 0) {
  proactive.forEach((s, i) => {
    proactiveText += `[${i+1}] type: ${s.type} | brand: ${s.brand_name || 'N/A'} | key: ${s.insight_key || 'N/A'} | ${s.message}\n`;
  });
  proactiveText += '\nNote: These suggestions have ALREADY been deduplicated against the last 24h of proactive events. Include them as pre_alert or proactive_trigger decisions.\n';
} else {
  proactiveText += 'No proactive patterns detected this cycle (all patterns already alerted in last 24h, or no patterns found).\n';
}

// Build dedup context for Gemini
let dedupText = '\n== RECENTLY SENT PROACTIVE ALERTS (last 24h — DO NOT REPEAT) ==\n';
if (recentProactive.length > 0) {
  const recentBrands = new Set();
  recentProactive.forEach((rp, i) => {
    const rpf = rp.fields || {};
    if (i < 10) {  // Show max 10 recent alerts
      dedupText += `- ${rpf.event_type || 'unknown'} | brand: ${rpf.brand_name || 'N/A'} | ${(rpf.message || '').substring(0, 120)}\n`;
    }
    if (rpf.brand_name) recentBrands.add(rpf.brand_name);
  });
  if (recentProactive.length > 10) {
    dedupText += `... and ${recentProactive.length - 10} more\n`;
  }
  dedupText += '\nCRITICAL DEDUP RULE: Do NOT generate pre_alert or proactive_trigger decisions for brands that already appear above (' + Array.from(recentBrands).join(', ') + '). These brands have already been alerted in the last 24 hours. Only generate proactive decisions for NEW patterns not listed above.\n';
} else {
  dedupText += 'No recent proactive alerts. You may generate new proactive insights if patterns warrant them.\n';
}

const systemMessage = 'You are the Orchestrator for a UGC creative agency automation system. You analyze events from various agents and project state to decide what actions to take next. Be conservative \u2014 only take actions that are clearly warranted by the data. NEVER repeat proactive alerts that were already sent in the last 24 hours. Output ONLY valid JSON.';

const userPrompt = eventsText + projectsText + brandsText + learningsText + proactiveText + dedupText + `\n== ALLOWED ACTIONS (whitelist \u2014 anything else will be REJECTED) ==\n1. trigger_phase: { phase: 3|4, project_id: "recXXX", client_code: "ABC-0123", webhook: "/webhook/ugc-scripts" or "/webhook/ugc-delivery" }\n2. notify_client: { project_id: "recXXX", brand_name: "X", client_code: "ABC-0123", message: "..." }\n3. escalate: { severity: "critical"|"high", brand_name: "X", message: "..." }\n4. sla_alert: { severity: "warning"|"urgent", project_id: "recXXX", brand_name: "X", message: "..." }\n5. suggest_new_cycle: { project_id: "recXXX", brand_name: "X", message: "..." }\n6. auto_onboard: { brand_name: "X", client_code: "ABC-0123" }\n7. scout_creators: { project_id: "recXXX", brand_name: "X", niches: ["X"], industry: "X", budget_max: 10000, count: 5, client_code: "ABC-0123" }\n8. no_action: { reason: "..." }\n9. pre_alert: { severity: "info", brand_name: "X", message: "...", project_id: "recXXX" (optional), insight_key: "..." }\n10. proactive_trigger: { action: "suggest_rotation"|"suggest_repurpose", brand_name: "X", message: "...", webhook: "/webhook/..." (optional), insight_key: "..." }\n\n== REASONING RULES ==\n- phase_complete from phase_1 \u2192 notify PM that research is complete + scout creators for that brand\n- phase_complete from phase_2 \u2192 trigger_phase 3 (scripts) + notify client\n- phase_complete from phase_3 \u2192 trigger_phase 4 (delivery) + notify client\n- phase_complete from phase_4 \u2192 notify client delivery complete\n- campaign_alert with fatigue \u2192 suggest_new_cycle ONLY if project has been delivered before\n- campaign_alert critical \u2192 escalate immediately\n- lead_action with stage Won \u2192 auto_onboard\n- sla_breach repeated 3+ times \u2192 escalate\n- status_change from onboarding \u2192 notify client\n- Reference System Learnings when making suggestions or providing context in messages\n- SLA thresholds: PM Review > 24h = warning, Script Review > 48h = warning, In Progress > 72h = urgent\n- Consolidate multiple events for same project into fewer actions\n- NEVER trigger phase 3 unless phase 2 completed (check project status)\n- NEVER trigger phase 4 unless phase 3 completed (check project status)\n- NEVER invent actions outside the allowed list\n- NEVER generate pre_alert or proactive_trigger for brands already alerted in RECENTLY SENT section\n- For trigger_phase 3, use webhook: "/webhook/ugc-scripts"\n- For trigger_phase 4, use webhook: "/webhook/ugc-delivery"\n- For scout_creators, infer industry and niches from brand/project data\n- For pre_alert and proactive_trigger, ALWAYS include the insight_key from the PROACTIVE INSIGHTS section\n\n== OUTPUT FORMAT ==\n{\n  "reasoning": "Brief 2-3 sentence analysis of the situation",\n  "decisions": [\n    { "type": "trigger_phase", "eventId": "recXXX", "phase": 3, "project_id": "recYYY", "client_code": "WHE-0217", "webhook": "/webhook/ugc-scripts", "message": "..." },\n    { "type": "notify_client", "eventId": "recXXX", "project_id": "recYYY", "brand_name": "X", "client_code": "WHE-0217", "message": "..." }\n  ]\n}\n\nAnalyze the events above and determine the appropriate actions.`;

const geminiBody = JSON.stringify({
  systemInstruction: { parts: [{ text: systemMessage }] },
  contents: [{ role: 'user', parts: [{ text: userPrompt }] }],
  generationConfig: { temperature: 0.1, maxOutputTokens: 4096, thinkingConfig: { thinkingBudget: 0 } }
});

return [{ json: { geminiBody, eventIds, eventCount: events.length, slaDecisions, _skipGemini: false } }];

// ============================================================
// Parse Gemini response and validate decisions
// Merges LLM decisions with hardcoded SLA decisions
// Falls back gracefully on parse failure
// ============================================================

const upstream = $('Build Orchestrator Prompt').first().json;
const slaDecisions = upstream.slaDecisions || [];
const eventIds = upstream.eventIds || [];

// If Gemini was skipped (0 events), output SLA decisions only
if (upstream._skipGemini) {
  return [{ json: {
    decisions: slaDecisions,
    eventIds,
    decisionCount: slaDecisions.length,
    eventCount: 0
  } }];
}

// Allowed action types
const allowedTypes = ['trigger_phase', 'notify_client', 'escalate', 'sla_alert', 'suggest_new_cycle', 'auto_onboard', 'scout_creators', 'no_action', 'pre_alert', 'proactive_trigger'];

// Required fields per action type
const requiredFields = {
  trigger_phase: ['phase', 'project_id'],
  notify_client: ['message', 'brand_name'],
  escalate: ['severity', 'message'],
  sla_alert: ['severity', 'message'],
  suggest_new_cycle: ['brand_name', 'message'],
  auto_onboard: ['brand_name'],
  scout_creators: ['brand_name'],
  no_action: ['reason'],
  pre_alert: ['message'],
  proactive_trigger: ['action', 'message']
};

let llmDecisions = [];
let reasoning = '';

try {
  const geminiResponse = $input.first().json;
  let rawText = '';

  // Extract text from Gemini response
  if (geminiResponse.candidates && geminiResponse.candidates[0]) {
    rawText = geminiResponse.candidates[0].content.parts[0].text || '';
  } else if (geminiResponse.error) {
    // Gemini returned an error \u2014 fall back to SLA only
    return [{ json: {
      decisions: slaDecisions,
      eventIds,
      decisionCount: slaDecisions.length,
      eventCount: upstream.eventCount,
      _geminiError: geminiResponse.error.message || 'Unknown Gemini error'
    } }];
  }

  // Strip markdown code fences
  rawText = rawText.replace(/^```json\s*/i, '').replace(/^```\s*/m, '').replace(/\s*```\s*$/m, '').trim();

  const parsed = JSON.parse(rawText);
  reasoning = parsed.reasoning || '';
  const rawDecisions = parsed.decisions || [];

  // Validate each decision
  for (const d of rawDecisions) {
    if (!d.type || !allowedTypes.includes(d.type)) continue;
    if (d.type === 'no_action') continue; // Skip no-action entries

    // Check required fields
    const required = requiredFields[d.type] || [];
    const missing = required.filter(f => !d[f] && d[f] !== 0);
    if (missing.length > 0) continue; // Skip invalid decisions

    // Add event reference and message if missing
    const decision = {
      type: d.type,
      eventId: d.eventId || eventIds[0] || '',
      ...d,
      message: d.message || `${d.type} action for ${d.brand_name || 'unknown'}`
    };

    // For trigger_phase, ensure webhook is set
    if (d.type === 'trigger_phase') {
      if (d.phase === 3) decision.webhook = '/webhook/ugc-scripts';
      if (d.phase === 4) decision.webhook = '/webhook/ugc-delivery';
    }

    llmDecisions.push(decision);
  }
} catch (e) {
  // JSON parse failed \u2014 fall back to SLA decisions only
  return [{ json: {
    decisions: slaDecisions,
    eventIds,
    decisionCount: slaDecisions.length,
    eventCount: upstream.eventCount,
    _parseError: e.message
  } }];
}

// Merge: LLM decisions + SLA decisions (deduplicate by project_id + type)
const seen = new Set();
const merged = [];

for (const d of llmDecisions) {
  const key = `${d.type}:${d.project_id || d.brand_name || ''}`;
  if (!seen.has(key)) {
    seen.add(key);
    merged.push(d);
  }
}

for (const d of slaDecisions) {
  const key = `${d.type}:${d.project_id || d.brand_name || ''}`;
  if (!seen.has(key)) {
    seen.add(key);
    merged.push(d);
  }
}

return [{ json: {
  decisions: merged,
  eventIds,
  decisionCount: merged.length,
  eventCount: upstream.eventCount,
  reasoning
} }];

